const $=s=>document.querySelector(s);
const themes={cosmic:{name:'Out of this world',terms:['space','time','science fiction'],book:'subject:science_fiction',movie:'space',music:'space ambient'},dream:{name:'A little surreal',terms:['dream','surreal','fantasy'],book:'subject:fantasy',movie:'fantasy',music:'dream pop'},heart:{name:'In my feelings',terms:['love','heart','romance','soul'],book:'subject:love',movie:'romance',music:'soul'},mystery:{name:'Something mysterious',terms:['mystery','crime','detective','thriller'],book:'subject:mystery',movie:'mystery',music:'noir jazz'},nature:{name:'A softer kind of magic',terms:['nature','magic','animation','adventure'],book:'subject:nature',movie:'animation',music:'folk'}};
const palette={film:['#201e1f','#daff02'],book:['#685bc7','#f3f0eb'],music:['#fe572a','#201e1f']};
function editorial(id,title,creator,type,theme,why,isbn){return{id,title,creator,type,theme,why,source:'Editorial pick',url:type==='book'?'https://openlibrary.org/search?q='+encodeURIComponent(title):type==='film'?'https://www.themoviedb.org/search?query='+encodeURIComponent(title):'https://musicbrainz.org/search?query='+encodeURIComponent(title)+'&type=release&method=indexed',image:isbn?'https://covers.openlibrary.org/b/isbn/'+isbn+'-L.jpg':'',description:why};}
const picks=[
editorial('e1','Interstellar','Christopher Nolan · 2014','film','cosmic','For the feeling of being tiny in a very big universe.'),
editorial('e2','The Left Hand of Darkness','Ursula K. Le Guin','book','cosmic','Another world. A deeply human question about belonging.','9780441478125'),
editorial('e3','Apollo: Atmospheres & Soundtracks','Brian Eno · 1983','music','cosmic','Quiet, expansive ambient music inspired by space exploration.'),
editorial('e4','Contact','Carl Sagan','book','cosmic','First contact, scientific wonder and the search for meaning.','9780671004101'),
editorial('e5','Inception','Christopher Nolan · 2010','film','dream','When the boundary between dreams and reality starts to dissolve.'),
editorial('e6','Piranesi','Susanna Clarke','book','dream','Get lost in a strange, beautiful world of impossible rooms.','9781635575637'),
editorial('e7','Bloom','Beach House · 2012','music','dream','Dream pop for the moments you want to drift somewhere else.'),
editorial('e8','The Ocean at the End of the Lane','Neil Gaiman','book','dream','Childhood memory meets uncanny magic.','9780062255655'),
editorial('e9','Her','Spike Jonze · 2013','film','heart','A tender exploration of intimacy, loneliness and connection.'),
editorial('e10','Normal People','Sally Rooney','book','heart','The complicated closeness between two people finding themselves.','9781984822178'),
editorial('e11','Blonde','Frank Ocean · 2016','music','heart','Fragmented memories, vulnerability and late-night introspection.'),
editorial('e12','Before Sunrise','Richard Linklater · 1995','film','heart','Two strangers, one night and a conversation that changes everything.'),
editorial('e13','Knives Out','Rian Johnson · 2019','film','mystery','Follow the clues through a family with plenty to hide.'),
editorial('e14','The Murder of Roger Ackroyd','Agatha Christie','book','mystery','A village mystery built for people who love being wrong-footed.','9780062073563'),
editorial('e15','The Third Man','Carol Reed · 1949','film','mystery','Atmospheric streets, uneasy friendships and a hidden truth.'),
editorial('e16','The Hound of the Baskervilles','Arthur Conan Doyle','book','mystery','A foggy moor and a legend that demands an explanation.','9780140437867'),
editorial('e17','My Neighbor Totoro','Hayao Miyazaki · 1988','film','nature','Everyday wonder, childhood and a little woodland magic.'),
editorial('e18','Braiding Sweetgrass','Robin Wall Kimmerer','book','nature','An invitation to rethink our relationship with the living world.','9781571313560'),
editorial('e19','Pink Moon','Nick Drake · 1972','music','nature','Spare, intimate folk for a slower afternoon.'),
editorial('e20','A Wizard of Earthsea','Ursula K. Le Guin','book','nature','An island world, a young wizard and the balance of nature.','9780547773742')];
const ICONS=['compass','layers','shuffle','info','shield-check','sun','moon','sun-moon','search','arrow-up-right','arrow-left','arrow-right','arrow-down','clapperboard','book-open','disc-3','image','x','plus','check','download','copy','bookmark'];
function icon(n){return `<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${ICONS.includes(n)?n:'compass'}"></use></svg>`}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cleanText=(s,n=300)=>typeof s==='string'?s.replace(/[\u0000-\u001f]/g,' ').slice(0,n):'';
const catalogueHosts=['openlibrary.org','www.tvmaze.com','www.themoviedb.org','musicbrainz.org','itunes.apple.com','music.apple.com','tv.apple.com','books.apple.com'];
function safeURL(u,image=false){if(image&&/^assets\/[a-z0-9._/-]+$/i.test(u||''))return u;try{const x=new URL(u);const hosts=image?['media.themoviedb.org','covers.openlibrary.org','static.tvmaze.com','is1-ssl.mzstatic.com','is2-ssl.mzstatic.com','is3-ssl.mzstatic.com','is4-ssl.mzstatic.com','is5-ssl.mzstatic.com','a1.mzstatic.com']:catalogueHosts;return x.protocol==='https:'&&hosts.includes(x.hostname)?x.href:''}catch{return ''}}
function valid(x){return x&&typeof x.id==='string'&&x.id.length<=180&&typeof x.title==='string'&&x.title.length>0&&x.title.length<=300&&['film','book','music'].includes(x.type)}
function normalize(x){if(!valid(x))return null;return{id:cleanText(x.id,180),title:cleanText(x.title),creator:cleanText(x.creator,200),type:x.type,source:cleanText(x.source,80)||'Shared pick',url:safeURL(x.url),image:safeURL(x.image,true),why:cleanText(x.why,500),description:cleanText(x.description,2500),genre:cleanText(x.genre,600),theme:themes[x.theme]?x.theme:null}}
let board=[];try{const b=JSON.parse(localStorage.getItem('rabbithole-board')||'[]');board=Array.isArray(b)?b.map(normalize).filter(Boolean).slice(0,60):[]}catch{}
let boardName='My wonderfully specific taste';try{boardName=cleanText(localStorage.getItem('rabbithole-board-name'),40)||boardName}catch{}
let experienced=new Set();try{const v=JSON.parse(localStorage.getItem('rabbithole-experienced')||'[]');if(Array.isArray(v))experienced=new Set(v.filter(x=>typeof x==='string'&&x.length<=180).slice(0,1000))}catch{}
const state={view:'discover',filter:'all',theme:'cosmic',items:picks.filter(x=>x.theme==='cosmic'),generation:0,limit:12,loading:false,shared:false};
const cache=new Map();let timer,lastSearch=0,currentSlide=0;const reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const slides=[{theme:'cosmic',seed:'e1',tag:'The cosmic connection',title:'A little further<br>from ordinary.',desc:'Big questions. Distant worlds. Music that makes time stand still.',art:'cosmic'}, {theme:'dream',seed:'e6',tag:'The dream connection',title:'Reality is<br>overrated.',desc:'Impossible rooms. Strange worlds. A soundtrack for getting lost.',art:'book'}, {theme:'heart',seed:'e11',tag:'The human connection',title:'For your<br>main-character era.',desc:'Beautifully complicated people. Stories and songs that stay with you.',art:'music'}];
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3300)}
function persist(){try{localStorage.setItem('rabbithole-board',JSON.stringify(board));localStorage.setItem('rabbithole-board-name',boardName);localStorage.setItem('rabbithole-experienced',JSON.stringify([...experienced]))}catch{notify('Storage is unavailable. Your board stays for this visit.')}}
function isSaved(x){return board.some(a=>a.id===x.id)}
function toggle(x){if(!x)return;if(isSaved(x)){board=board.filter(a=>a.id!==x.id);notify('Removed from your universe.')}else{if(board.length>=60)return notify('Your universe holds 60 discoveries. Remove one to add another.');board.push(normalize(x));notify('Added to your universe.')}persist();const focused=document.activeElement?.dataset?.save;render();if(focused)for(const b of document.querySelectorAll('[data-save]'))if(b.dataset.save===focused)b.focus()}
function graphic(x,hidden=false){const p=palette[x.type];return `<div class="cover-graphic" ${hidden?'hidden':''} style="--cover:${p[0]};--cover-ink:${p[1]}"><span>${x.type==='film'?'A different point of view':x.type==='book'?'Between these pages':'Find your frequency'}</span><strong>${esc(x.title)}</strong><span class="cover-symbol" aria-hidden="true">${x.type==='music'?'◎':x.type==='book'?'↗':'◌'}</span></div>`}
function cover(x,eager=false){const u=safeURL(x.image,true);return u?`<img src="${esc(u)}" alt="${esc(x.title)} cover" loading="${eager?'eager':'lazy'}" decoding="async">${graphic(x,true)}`:graphic(x)}
function listItems(){return(state.view==='board'?board:state.items).filter(x=>state.filter==='all'||x.type===state.filter)}
function render(){const filtered=listItems(),visible=filtered.slice(0,state.limit);$('#results').innerHTML=visible.map((x,i)=>`<article class="card" style="--i:${Math.min(i,7)}"><div class="art"><button data-open="${esc(x.id)}" aria-label="Explore ${esc(x.title)}">${cover(x,i<4)}</button><button class="save ${isSaved(x)?'saved':''}" data-save="${esc(x.id)}" aria-pressed="${isSaved(x)}" aria-label="${isSaved(x)?'Remove':'Save'} ${esc(x.title)}">${icon(isSaved(x)?'check':'plus')}</button></div><p class="kind"><span class="type-dot">${x.type==='film'?'Watch':x.type==='book'?'Read':'Listen'}</span><span>${esc(x.source)}</span></p><h3><button data-open="${esc(x.id)}">${esc(x.title)}</button></h3><p class="creator">${esc(x.creator)}</p>${experienced.has(x.id)?'<span class="experienced-tag">'+icon('check')+({film:'Watched',book:'Read',music:'Listened'}[x.type])+'</span>':''}<p class="reason"><span class="connection">↳</span> ${esc(x.why||'Open this discovery to follow its connection.')}</p></article>`).join('');$('#empty').hidden=filtered.length>0||state.loading;$('#count').textContent=board.length;$('#result-count').textContent=filtered.length+' discoveries';$('#load-more').hidden=visible.length>=filtered.length;$('#hero').hidden=state.view==='board'||state.shared;$('#board-intro').hidden=state.view!=='board';$('#moods').hidden=state.view==='board'||state.shared;$('.closing').hidden=state.view==='board'||state.shared;$('#loading').hidden=!state.loading;document.body.classList.toggle('searching',state.loading);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view))});document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter))});document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('selected',b.dataset.theme===state.theme);b.setAttribute('aria-pressed',String(b.dataset.theme===state.theme))});if(state.view==='board'){$('#heading').textContent='The things that make you, you.';$('#context').textContent=boardName;$('#status').textContent='Saved on this device. Create a taste card or share a snapshot.';$('#board-name').value=boardName;$('#board-stats').innerHTML=['film','book','music'].map((type,i)=>`<span><strong>${board.filter(x=>x.type===type).length}</strong>${['to watch','to read','to hear'][i]}</span>`).join('')}const done=board.filter(x=>experienced.has(x.id)).length;$('#progress-summary').innerHTML='<strong>'+done+' of '+board.length+'</strong> saved discoveries explored.<div class="progress-track" role="progressbar" aria-label="Saved discoveries explored" aria-valuemin="0" aria-valuemax="'+Math.max(1,board.length)+'" aria-valuenow="'+done+'"><span style="width:'+ (board.length?Math.round(done/board.length*100):0)+'%"></span></div>';requestAnimationFrame(updateTabs)}
function updateTabs(){const active=$('.tabs .active');if(!active)return;const p=active.parentElement;$('.tab-indicator').style.width=active.offsetWidth+'px';$('.tab-indicator').style.transform=`translateX(${active.offsetLeft-4}px)`}
function find(id){return[...state.items,...board,...picks].find(x=>x.id===id)}
function modal(html){$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0}
function detail(x){if(!x)return;modal(`<div class="detail-layout"><div class="detail-cover">${cover(x,true)}</div><div><p class="kind">${x.type==='film'?'Watch':x.type==='book'?'Read':'Listen'} / ${esc(x.source)}</p><h2 id="dialog-title">${esc(x.title)}</h2><p class="detail-creator">${esc(x.creator)}</p><p>${esc(x.description||x.why)}</p><div class="detail-why"><strong>Why this connection?</strong><p>${esc(x.why||'A related catalogue match. Explore the source to see if it fits.')}</p></div>${safeURL(x.url)?`<a class="source-link" href="${esc(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">${x.source==='Apple catalogue'?'View on Apple Store':'View source catalogue'} ↗</a>`:''}<div class="detail-actions"><button class="secondary" id="inspiration">Follow the inspiration ↗</button><button class="primary" id="modal-save">${icon(isSaved(x)?'check':'plus')}${isSaved(x)?'Saved — remove':'Save to universe'}</button><button class="secondary" id="experienced">${icon(experienced.has(x.id)?'check':'plus')}${experienced.has(x.id)?'Explored — undo':({film:'Mark watched',book:'Mark read',music:'Mark listened'}[x.type])}</button><button class="secondary" id="follow">Follow this thread ${icon('arrow-up-right')}</button></div></div></div>`);$('#inspiration').onclick=()=>showInspiration(x);$('#modal-save').onclick=()=>{toggle(x);$('#modal-save').innerHTML=icon(isSaved(x)?'check':'plus')+(isSaved(x)?'Saved — remove':'Save to universe')};$('#experienced').onclick=()=>{if(experienced.has(x.id))experienced.delete(x.id);else experienced.add(x.id);persist();render();detail(x)};$('#follow').onclick=()=>askTaste(x)}
function infer(x){if(themes[x.theme])return x.theme;const text=(x.title+' '+x.description+' '+x.genre).toLowerCase();for(const[k,v]of Object.entries(themes))if(v.terms.some(t=>text.includes(t)))return k;return null}
async function json(url){if(cache.has(url))return cache.get(url);const r=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('Catalogue unavailable');const j=await r.json();cache.set(url,j);return j}
function apple(term,media){const key=term+'|'+media;if(cache.has(key))return Promise.resolve(cache.get(key));return new Promise((resolve,reject)=>{const name='rh'+crypto.randomUUID().replaceAll('-','');const script=document.createElement('script');let t;const cleanup=()=>{script.remove();delete window[name];clearTimeout(t)};window[name]=j=>{cleanup();cache.set(key,j);resolve(j)};script.src='https://itunes.apple.com/search?'+new URLSearchParams({term,media,entity:media==='music'?'album':'movie',limit:'6',explicit:'No',country:'US',callback:name});script.onerror=()=>{cleanup();reject(Error('Apple unavailable'))};t=setTimeout(()=>{cleanup();reject(Error('Apple timed out'))},12000);document.head.append(script)})}
function appleItems(j,type,why){return(j.results||[]).slice(0,8).map(x=>normalize({id:'apple'+(x.trackId||x.collectionId),title:x.trackName||x.collectionName,creator:x.artistName||'',type,source:'Apple catalogue',image:x.artworkUrl100?.replace('100x100bb','600x600bb')||'',url:x.trackViewUrl||x.collectionViewUrl,description:x.longDescription||x.shortDescription||x.primaryGenreName||'',genre:x.primaryGenreName,why})).filter(Boolean)}
async function books(term,why){const j=await json('https://openlibrary.org/search.json?'+new URLSearchParams({q:term,limit:'6',fields:'key,title,author_name,cover_i,first_publish_year,subject'}));return(j.docs||[]).map(x=>normalize({id:'ol'+x.key,title:x.title,creator:(x.author_name||[]).slice(0,2).join(', '),type:'book',source:'Open Library',image:x.cover_i?'https://covers.openlibrary.org/b/id/'+x.cover_i+'-L.jpg':'',url:'https://openlibrary.org'+x.key,description:(x.subject||[]).slice(0,8).join(', '),genre:(x.subject||[]).join(' '),why})).filter(Boolean)}
async function television(term,why){const j=await json('https://api.tvmaze.com/search/shows?q='+encodeURIComponent(term));return j.slice(0,4).map(({show:x})=>normalize({id:'tv'+x.id,title:x.name,creator:'TV series'+(x.premiered?' · '+x.premiered.slice(0,4):''),type:'film',source:'TVmaze',image:x.image?.medium||'',url:x.url,description:(x.summary||'').replace(/<[^>]*>/g,''),genre:(x.genres||[]).join(' '),why})).filter(Boolean)}
const unique=xs=>[...new Map(xs.filter(Boolean).map(x=>[x.id,x])).values()];
function interleave(groups){const out=[];for(let i=0;i<Math.max(0,...groups.map(x=>x.length));i++)for(const g of groups)if(g[i])out.push(g[i]);return unique(out)}
function scrollResults(){$('.explore').scrollIntoView({behavior:reduce()?'instant':'smooth',block:'start'})}
async function search(term){term=cleanText(term,100).trim();if(!term)return;if(Date.now()-lastSearch<2500)return notify('Give the catalogues a moment before searching again.');lastSearch=Date.now();const n=++state.generation;Object.assign(state,{view:'discover',filter:'all',shared:false,limit:12,loading:true,items:[]});$('#query').value=term;$('#heading').textContent='Your starting points.';$('#context').textContent='Searching for “'+term+'”';$('#status').textContent='Connecting films, books, music and television…';render();scrollResults();const r=await Promise.allSettled([apple(term,'movie').then(j=>appleItems(j,'film','A title or metadata match to your search.')),books(term,'A title or metadata match to your search.'),apple(term,'music').then(j=>appleItems(j,'music','An artist, album or metadata match to your search.')),television(term,'A television catalogue match to your search.')]);if(n!==state.generation)return;state.loading=false;state.items=interleave(r.map(x=>x.status==='fulfilled'?x.value:[]));$('#status').textContent=`${state.items.length} catalogue matches. ${r.some(x=>x.status==='rejected')?'Some sources are unavailable. ':''}Open a result to follow its thread.`;render()}
async function discover(seed,facet=null){if(!seed)return;const theme=infer(seed);const n=++state.generation;Object.assign(state,{view:'discover',filter:'all',theme,shared:false,limit:12,loading:true,items:theme?picks.filter(x=>x.theme===theme&&x.id!==seed.id):[]});const name=theme?themes[theme].name:'A new direction';$('#heading').textContent=name+'.';$('#context').textContent='Because you love '+seed.title;$('#status').textContent='Connecting the dots across catalogues…';render();scrollResults();const base=theme?themes[theme]:{book:seed.title,movie:seed.title,music:seed.creator||seed.title};const f=tasteFacets[facet];const t=f?{book:base.book+' '+f.book,movie:base.movie+' '+f.movie,music:base.music+' '+f.music}:base;const why=(f?'Your choice: '+f.label.toLowerCase()+'. ':'')+(theme?'Connected by theme: '+name.toLowerCase()+'.':'A related title or creator search.');const r=await Promise.allSettled([books(t.book,why),apple(t.movie,'movie').then(j=>appleItems(j,'film',why)),apple(t.music,'music').then(j=>appleItems(j,'music',why))]);if(n!==state.generation)return;state.loading=false;const live=interleave(r.map(x=>x.status==='fulfilled'?x.value:[]));state.items=unique([...state.items,...live]);$('#status').textContent=`${theme?'Editorial picks + ':''}${live.length} catalogue matches. ${r.some(x=>x.status==='rejected')?'Some sources are unavailable. ':''}${f?'Guided by your choice: '+f.label.toLowerCase()+'. ':''}Connections use themes and catalogue metadata.`;render()}
function view(v){state.generation++;Object.assign(state,{view:v,filter:'all',shared:false,limit:12,loading:false});if(v==='discover'){$('#heading').textContent='Find your frequency.';$('#context').textContent='A good place to get wonderfully lost.';$('#status').textContent='Handpicked connections. Search above for live catalogue results.';state.items=picks.filter(x=>x.theme===(state.theme||'cosmic'))}render();scrollTo({top:0,behavior:reduce()?'instant':'smooth'})}
function chooseTheme(k){state.generation++;Object.assign(state,{view:'discover',theme:k,shared:false,filter:'all',limit:12,loading:false,items:picks.filter(x=>x.theme===k)});$('#heading').textContent=themes[k].name+'.';$('#context').textContent='A different frequency. A new starting point.';$('#status').textContent='Handpicked connections. Open one to follow its thread across catalogues.';render()}
function setTheme(mode){document.documentElement.dataset.theme=mode;document.querySelector('meta[name="theme-color"]').content=mode==='dark'?'#171617':'#f3f0eb'}
function slide(i){currentSlide=(i+slides.length)%slides.length;const s=slides[currentSlide];$('.feature-tag').textContent=s.tag;$('.feature-copy h2').innerHTML=s.title;$('.feature-copy>p').textContent=s.desc;$('.feature-image').innerHTML=s.art==='cosmic'?'<img src="assets/cosmic.png" alt="Original cosmic artwork of an explorer beneath a glowing black hole"><div class="image-caption">Original thematic artwork</div>':s.art==='book'?'<div class="book-scene"><img src="https://covers.openlibrary.org/b/isbn/9781635575637-L.jpg" alt="Piranesi by Susanna Clarke"></div><div class="image-caption">Book cover · Open Library</div>':'<div class="music-scene"><div class="vinyl-record" role="img" aria-label="Illustrated vinyl record"></div></div><div class="image-caption">Original thematic illustration</div>';$('#feature-slide').getAnimations().forEach(a=>a.cancel());if(!reduce())$('#feature-slide').animate([{opacity:.25,transform:'translateX(14px)'},{opacity:1,transform:'none'}],{duration:380,easing:'cubic-bezier(.22,1,.36,1)'});document.querySelectorAll('[data-slide]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.slide===currentSlide)));$('#slide-announcement').textContent='Thread '+(currentSlide+1)+' of '+slides.length}
function surprise(){const x=picks[Math.floor(Math.random()*picks.length)];detail(x)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open)detail(find(b.dataset.open));if(b.dataset.save)toggle(find(b.dataset.save));if(b.dataset.filter){state.filter=b.dataset.filter;state.limit=12;render()}if(b.dataset.view)view(b.dataset.view);if(b.dataset.seed){const seed=b.dataset.seed;const x=picks.find(x=>x.title===seed||x.creator.includes(seed));askTaste(x||{title:seed,theme:'nature'})}if(themes[b.dataset.theme])chooseTheme(b.dataset.theme);if(b.dataset.slide!==undefined)slide(+b.dataset.slide)});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const fallback=e.target.nextElementSibling;if(fallback?.classList.contains('cover-graphic')){e.target.hidden=true;fallback.hidden=false}}},true);
$('#search').onsubmit=e=>{e.preventDefault();search($('#query').value)};$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};$('#board-cta').onclick=()=>view('board');$('#reset').onclick=()=>view('discover');$('#load-more').onclick=()=>{state.limit+=12;render()};$('#surprise').onclick=surprise;$('#mobile-surprise').onclick=surprise;$('#mobile-about').onclick=()=>$('#about').click();$('#feature-action').onclick=()=>askTaste(picks.find(x=>x.id===slides[currentSlide].seed));$('#prev-slide').onclick=()=>slide(currentSlide-1);$('#next-slide').onclick=()=>slide(currentSlide+1);$('#feature-carousel').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();slide(currentSlide+(e.key==='ArrowRight'?1:-1))}};let swipeStart=0;$('#feature-carousel').addEventListener('touchstart',e=>{swipeStart=e.changedTouches[0].clientX},{passive:true});$('#feature-carousel').addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-swipeStart;if(Math.abs(delta)>60)slide(currentSlide+(delta<0?1:-1))},{passive:true});$('#board-name').oninput=e=>{boardName=cleanText(e.target.value,40);persist();$('#context').textContent=boardName||'My wonderfully specific taste'};window.addEventListener('resize',updateTabs);
$('#about').onclick=()=>modal(`<h2 id="dialog-title">A good kind of rabbit hole.</h2><p>Search for something you love. Open a discovery, follow its thread and find films, books and music connected by theme.</p><p>Save the things that feel like you. Give your universe a name, then create a taste card or share a snapshot.</p><p class="modal-notes">Editorial picks and theme searches are clearly labelled. This version does not claim AI-powered personalisation. No account needed; your saved universe lives on this device.</p><button class="primary" id="about-board">See my universe ${icon('arrow-up-right')}</button>`);
$('#sources').onclick=()=>modal(`<h2 id="dialog-title">Sources. Clearly connected.</h2><div class="source-grid"><a href="https://openlibrary.org/developers/api" target="_blank" rel="noopener">Open Library <span>Books & covers ↗</span></a><a href="https://www.tvmaze.com/api" target="_blank" rel="noopener">TVmaze <span>Television · CC BY-SA ↗</span></a><a href="https://performance-partners.apple.com/search-api" target="_blank" rel="noopener">Apple Search API <span>Films & albums ↗</span></a></div><p>Apple searches use the US storefront. Availability differs by country. Movie posters are sourced from TMDB; book covers from Open Library and album artwork from Apple where available. TMDB does not endorse this app. Hero artwork and typographic fallbacks are original.</p><p>Your board is stored in your browser. Appearance follows your device setting. Shared links contain a snapshot of the titles you select. Anyone with access to the app and your link can read that snapshot. There are no account passwords or private API keys in this app.</p><p>Catalogue services receive search requests. Image services receive cover requests. Firecrawl receives featured-title searches when you open inspiration sources. This app installs no analytics. Shared content is length-limited and rendered as text; links are restricted to known catalogue providers.</p><p class="modal-notes">Interaction references: <a href="https://smoothui.dev/docs/components" target="_blank" rel="noopener">SmoothUI</a> and <a href="https://www.inspora.design" target="_blank" rel="noopener">Inspora</a>. Icons: <a href="https://lucide.dev" target="_blank" rel="noopener">Lucide</a>, ISC licence.</p>`);
document.addEventListener('click',e=>{if(e.target.closest('#about-board')){$('#detail').close();view('board')}});
function sharedURL(){const snapshot=board.slice(0,30).map(({id,title,creator,type,source,url,image,why,theme})=>({id,title,creator,type,source,url,image,why,theme}));const bytes=new TextEncoder().encode(JSON.stringify({name:boardName,items:snapshot}));return location.origin+location.pathname+'#universe='+encodeURIComponent(btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')))}
async function shareUniverse(){if(!board.length){notify('Save a few discoveries to start your universe.');return}const url=sharedURL();try{if(navigator.share)await navigator.share({title:boardName||'My RabbitHole universe',text:'These are my kind of things. What are yours?',url});else{await navigator.clipboard.writeText(url);notify('Universe link copied. Send someone down your rabbit hole.')}}catch(e){if(e.name!=='AbortError')modal(`<h2 id="dialog-title">Your universe link</h2><p>Copy this link to share your snapshot.</p><textarea aria-label="Universe link" class="share-url">${esc(url)}</textarea>`)}}
$('#share').onclick=shareUniverse;
function wrapText(ctx,text,x,y,maxWidth,lineHeight,maxLines=3){const words=String(text).split(/\s+/);const lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);const visible=lines.slice(0,maxLines);if(lines.length>maxLines){let last=visible[visible.length-1];while(ctx.measureText(last+'…').width>maxWidth&&last.length)last=last.slice(0,-1);visible[visible.length-1]=last+'…'}visible.forEach((v,i)=>ctx.fillText(v,x,y+i*lineHeight,maxWidth));return y+(visible.length-1)*lineHeight}
async function tasteCard(){if(!board.length)return notify('Save a few discoveries before making your taste card.');await document.fonts.ready;modal(`<h2 id="dialog-title">Your taste. In one frame.</h2><p>Made to be shared. Your universe, without the screenshots.</p><canvas id="taste-canvas" class="taste-canvas" width="1080" height="1350" aria-label="Your personalised RabbitHole taste card"></canvas><div class="detail-actions"><button class="primary" id="download-card">${icon('download')}Download PNG</button><button class="secondary" id="copy-board">${icon('copy')}Share universe link</button></div>`);const c=$('#taste-canvas'),g=c.getContext('2d');g.fillStyle='#201e1f';g.fillRect(0,0,1080,1350);g.fillStyle='#daff02';g.font='800 42px League Spartan, sans-serif';g.fillText('rabbithole',70,100);g.font='600 24px League Spartan, sans-serif';g.fillStyle='#f3f0eb';g.fillText('A FEW THINGS THAT FEEL LIKE ME',70,165);g.font='700 83px League Spartan, sans-serif';wrapText(g,boardName||'My wonderfully specific taste',70,295,920,90,3);let y=555;for(const [i,x]of board.slice(0,6).entries()){g.fillStyle=['#daff02','#fe572a','#a79ce8'][i%3];g.beginPath();g.arc(86,y-12,7,0,Math.PI*2);g.fill();g.fillStyle='#f3f0eb';g.font='700 31px League Spartan, sans-serif';wrapText(g,x.title,115,y,850,35,1);g.fillStyle='#aaa2a7';g.font='400 21px League Spartan, sans-serif';g.fillText((x.type==='film'?'WATCH':x.type==='book'?'READ':'LISTEN')+' / '+x.creator.slice(0,55),115,y+36);y+=96}g.fillStyle='#685bc7';g.fillRect(0,1190,1080,160);g.fillStyle='#f3f0eb';g.font='600 29px League Spartan, sans-serif';g.fillText('Good taste travels.',70,1255);g.font='400 21px League Spartan, sans-serif';g.fillText('Build your universe on RabbitHole.',70,1300);$('#download-card').onclick=()=>{c.toBlob(blob=>{if(!blob)return notify('Your browser could not create the image.');const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='my-rabbithole-taste.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);notify('Taste card downloaded.')},'image/png')};$('#copy-board').onclick=shareUniverse}
$('#taste-card').onclick=tasteCard;
try{if(location.hash.startsWith('#universe=')){const encoded=decodeURIComponent(location.hash.slice(10));if(encoded.length>60000)throw Error('Too large');const bytes=Uint8Array.from(atob(encoded),x=>x.charCodeAt(0));const payload=JSON.parse(new TextDecoder().decode(bytes));const arr=Array.isArray(payload)?payload:payload.items;if(!Array.isArray(arr))throw Error('Invalid board');state.items=unique(arr.map(normalize).filter(Boolean).slice(0,30));state.shared=true;$('#heading').textContent=cleanText(payload.name,40)||'A universe shared with you.';$('#context').textContent='Someone thinks you should see these.';$('#status').textContent='A shared snapshot. Save anything you love to make it yours.'}}catch{notify('This universe link is incomplete or invalid.')}
// Catalogue artwork is resolved lazily; original hero artwork remains clearly labelled.
icons();setTheme(document.documentElement.dataset.theme==='dark'?'dark':'light');render();

document.querySelectorAll('.wordmark,.mobile-brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();view('discover')}));


const tasteFacets={story:{label:'The story',book:'adventure',movie:'drama',music:'storytelling'},atmosphere:{label:'The atmosphere',book:'atmospheric',movie:'mystery',music:'ambient'},characters:{label:'The characters',book:'relationships',movie:'relationships',music:'soul'},visuals:{label:'The visuals',book:'illustrated',movie:'fantasy',music:'cinematic'},soundtrack:{label:'The soundtrack',book:'music',movie:'music',music:'soundtrack'}};
function askTaste(seed){if(!seed)return;modal(`<p class="eyeline">Follow what moved you</p><h2 id="dialog-title">What did you love about ${esc(seed.title)}?</h2><p>Pick a direction. We'll use it to guide searches across films, books and music.</p><div class="taste-choices">${Object.entries(tasteFacets).map(([k,f])=>`<button class="taste-choice" data-taste="${k}">${esc(f.label)} <span>↗</span></button>`).join('')}</div><button class="secondary" id="taste-any">A bit of everything ↗</button><p class="modal-notes">These are theme and metadata searches, not an AI taste prediction.</p>`);document.querySelectorAll('[data-taste]').forEach(b=>b.onclick=()=>{$('#detail').close();discover(seed,b.dataset.taste)});$('#taste-any').onclick=()=>{$('#detail').close();discover(seed);}}

const researchedConnections={e1:[{title:'The Science of Interstellar',url:'https://wwnorton.com/books/9780393351378',note:'A companion book by the film’s science adviser, Kip Thorne. Explore black holes, wormholes and the science behind the film.',kind:'Verified companion',publisher:'W. W. Norton'}]};
function webSource(u){try{const x=new URL(u);return x.protocol==='https:'&&!x.username&&!x.password?x.href:''}catch{return ''}}
let inspirationRequest=0;
async function showInspiration(seed){const request=++inspirationRequest;modal(`<p class="eyeline">Follow the inspiration</p><h2 id="dialog-title">Behind ${esc(seed.title)}</h2><div id="inspiration-results" aria-live="polite"><p>Finding interviews, influences and deeper reading…</p></div><button class="secondary" id="inspiration-back">Back to discovery</button>`);$('#inspiration-back').onclick=()=>{inspirationRequest++;detail(seed)};const known=picks.find(p=>p.id===seed.id||p.title.toLowerCase()===seed.title.toLowerCase());let found=[],live=false;try{if(known){const r=await fetch('/api/inspiration?id='+encodeURIComponent(known.id),{signal:AbortSignal.timeout(18000)});if(r.ok){const j=await r.json();found=Array.isArray(j.items)?j.items.slice(0,3):[];live=true}}}catch{}if(request!==inspirationRequest)return;const verified=researchedConnections[known?.id]||[];$('#inspiration-results').innerHTML=verified.map(x=>`<article class="inspiration-card"><span class="source-badge">${esc(x.kind)}</span><h3>${esc(x.title)}</h3><p>${esc(x.note)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.publisher)} ↗</a></article>`).join('')+found.filter(x=>webSource(x.url)&&!verified.some(v=>v.url===x.url)).map(x=>`<article class="inspiration-card"><span class="source-badge">Web source · explore the evidence</span><h3>${esc(cleanText(x.title,160))}</h3><a href="${esc(webSource(x.url))}" target="_blank" rel="noopener noreferrer">Read source ↗</a></article>`).join('')+`<p class="modal-notes">${live?'Web sources found with Firecrawl. A search result is not proof of an influence.':verified.length?'Showing researched connections. Live web discovery is temporarily unavailable.':'No verified connection is available for this title yet. Try a featured discovery, or follow a thematic thread.'} ${verified.length?'Companion connection checked against the publisher on 19 October 2026.':''}</p>`;}
// Resolve only the visible editorial shelf on idle, then other shelves when selected.
function loadVisibleArtwork(){const targets=picks.filter(x=>x.theme===state.theme&&!x.image&&x.type!=='book');for(const x of targets){apple(x.title,x.type==='music'?'music':'movie').then(j=>{const norm=t=>t.toLowerCase().replace(/[^a-z0-9]/g,'');const match=(j.results||[]).find(r=>norm(r.trackName||r.collectionName||'')===norm(x.title));const u=safeURL(match?.artworkUrl100?.replace('100x100bb','600x600bb'),true);if(u){x.image=u;if(state.view==='discover')render()}}).catch(()=>{});}}
const originalChooseTheme=chooseTheme;chooseTheme=function(k){originalChooseTheme(k);loadVisibleArtwork()};
if(typeof window.requestIdleCallback==='function')window.requestIdleCallback(loadVisibleArtwork,{timeout:2000});else setTimeout(loadVisibleArtwork,1000);

